insert into public.maison_products(slug,data,status,stock) values('automobile-tee','{"slug":"automobile-tee","name":"Automobile Tee","price":450,"edition":"Edition 001","artMark":"AUTO","shortDescription":"The automobile graphic, finished with a collage of house references.","description":"A black everyday tee with a front automobile graphic, a printed back collage and a detailed sleeve patch graphic. The original garment photography shows the design as it is.","tone":"#151515","ink":"#f4f0e7","images":["/Automobile front.jpg","/Automobile 2.jpg","/Automobile back.jpg","/PHOTO-2026-06-02-15-55-29.jpg"],"imageLabels":["Front","Back","Back detail","Archive graphic"],"category":"apparel"}'::jsonb,'published','{"S":0,"M":0,"L":0,"XL":0}'::jsonb) on conflict(slug) do nothing;
