insert into public.maison_products(slug,data,status,stock) values('boat-floating-wheel','{"slug":"boat-floating-wheel","name":"Boat Floating Wheel","price":60,"category":"accessory","edition":"Accessories / 001","artMark":"WHEEL","shortDescription":"A subtle statement piece designed to elevate whatever you wear it on.","description":"A boat wheel-inspired floating lapel accessory designed to subtly stand out and elevate any item it is worn on. Finished in black with red detailing. Dimensions: 29 mm × 30 mm.","tone":"#ffffff","ink":"#161616","images":["/products/boat-floating-wheel/boat-front.jpeg","/products/boat-floating-wheel/boat-detail.jpeg","/products/boat-floating-wheel/boat-lifestyle.jpeg"],"imageLabels":["Front","Detail","Lifestyle"]}'::jsonb,'published','{"ONE SIZE":0}'::jsonb) on conflict(slug) do nothing;
